function mcPortableCrypt($data, $key) {
    $out = '';
    $n = 0;
    $len = strlen($data);
    $block = '';
    while ($n < $len) {
        if (($n % 32) === 0) {
            $block = hash('sha256', $key . pack('N', (int)($n / 32)), true);
        }
        $out .= $data[$n] ^ $block[$n % 32];
        $n++;
    }
    return $out;
}

function safeDecrypt($data, $key) {
    $decoded = base64_decode($data);
    if ($decoded === false) { return null; }
    $decrypted = mcPortableCrypt($decoded, $key);
    $inner = base64_decode($decrypted);
    if ($inner === false) { return null; }
    $plain = @gzinflate($inner);
    if ($plain === false) { return null; }
    return $plain;
}

